eventOn('mag_variable_update_started', variableUpdateStarted);
eventOn('mag_variable_updated', variableUpdated);
eventOn('mag_variable_update_ended', variableUpdateEnded);

/**
 * A boolean flag that is set to true when the in-game time crosses midnight.
 * It is reset at the start of each variable update cycle.
 */
let dayHasPassed = false;

/**
 * Stores the initial value of "经过天数" at the beginning of an update cycle.
 * This is used to check if the value was modified by other processes (e.g., the AI).
 */
let initialDaysPassed = 0;

/**
 * 属性列表，用于遍历所有需要检查的属性
 */
const attributeList = ['力量', '敏捷', '耐力', '感知', '智力', '意志'];

/**
 * Converts a time string in "HH:MM" format to a comparable number.
 *
 * @param {string} timeStr - The time string, e.g., "23:59".
 * @returns {number} The numeric representation, e.g., 2359. Returns 0 if input is invalid.
 */
function parseTimeToNumber(timeStr) {
    if (!timeStr || typeof timeStr !== 'string') return 0;
    const [hours, minutes] = timeStr.split(':').map(Number);
    return (hours || 0) * 100 + (minutes || 0);
}

/**
 * Called at the start of a variable update cycle. It initializes state for tracking day changes.
 *
 * @param {Record<string, any>} variables - The global variables object.
 * @param {boolean} out_is_updated - A flag indicating if updates have already occurred.
 * @returns {void}
 */
function variableUpdateStarted(variables, out_is_updated) {
    dayHasPassed = false;
    // --- 修正点 1 ---
    // 从数组的第一个元素 [0] 读取数值，并确保是数字类型
    initialDaysPassed = Number(variables.stat_data.世界.经过天数[0]) || 0;
    out_is_updated = out_is_updated || false;
}

/**
 * Called for each individual variable update. It detects when a day passes.
 *
 * @param {Record<string, any>} _stat_data - The data structure of the updated variables.
 * @param {string} path - The path of the updated variable, e.g., "世界.时间".
 * @param {any} _oldValue - The previous value of the variable.
 * @param {any} _newValue - The new value of the variable.
 * @returns {void}
 */
function variableUpdated(_stat_data, path, _oldValue, _newValue) {
    // 假设 "世界.时间" 的值也是一个数组 [value, description]
    const newTime = Array.isArray(_newValue) ? _newValue[0] : _newValue;
    const oldTime = Array.isArray(_oldValue) ? _oldValue[0] : _oldValue;

    if (path === '世界.时间') {
        const newTimeNum = parseTimeToNumber(newTime);
        const oldTimeNum = parseTimeToNumber(oldTime);
        if (newTimeNum < oldTimeNum) {
            dayHasPassed = true;
        }
    }
}

/**
 * 更新属性等级
 *
 * @param {Record<string, any>} variables - 全局变量对象
 * @param {string} attrName - 属性名称
 * @returns {boolean} - 是否进行了更新
 */
function updateAttribute(variables, attrName) {
    if (!variables.stat_data.属性 || !variables.stat_data.属性[attrName]) {
        return false;
    }

    const attr = variables.stat_data.属性[attrName];
    const currentExp = Number(attr.当前经验[0]) || 0;
    const requiredExp = Number(attr.升级所需经验[0]) || 0;
    const currentLevel = Number(attr.等级[0]) || 0;

    // 检查是否满足升级条件
    if (currentExp >= requiredExp) {
        // 升级属性
        const newLevel = currentLevel + 1;
        attr.等级[0] = newLevel;
        attr.当前经验[0] = Math.max(0, currentExp - requiredExp);
        attr.升级所需经验[0] = newLevel * 10;

        // 记录显示信息
        if (!variables.display_data) {
            variables.display_data = {};
        }
        variables.display_data[`${attrName}等级`] = `${currentLevel} -> ${newLevel} (属性升级)`;

        return true;
    }

    return false;
}

/**
 * 更新技能等级
 *
 * @param {Record<string, any>} variables - 全局变量对象
 * @returns {boolean} - 是否进行了更新
 */
function updateSkills(variables) {
    if (!variables.stat_data.技能) {
        return false;
    }

    let updated = false;

    // 遍历所有技能
    Object.keys(variables.stat_data.技能).forEach(skillName => {
        if (skillName === '$meta') return;

        const skill = variables.stat_data.技能[skillName];
        if (!skill) return;

        const currentExp = Number(skill.当前经验[0]) || 0;
        const requiredExp = Number(skill.升级所需经验[0]) || 0;
        const currentLevel = Number(skill.等级[0]) || 0;

        // 检查是否满足升级条件
        if (currentExp >= requiredExp) {
            // 升级技能
            const newLevel = currentLevel + 1;
            skill.等级[0] = newLevel;
            skill.当前经验[0] = Math.max(0, currentExp - requiredExp);
            skill.升级所需经验[0] = newLevel * 100;

            // 记录显示信息
            if (!variables.display_data) {
                variables.display_data = {};
            }
            variables.display_data[`${skillName}等级`] = `${currentLevel} -> ${newLevel} (技能升级)`;

            updated = true;
        }
    });

    return updated;
}

/**
 * 更新派生属性
 * 
 * @param {Record<string, any>} variables - 全局变量对象
 * @returns {boolean} - 是否进行了更新
 */
function updateDerivedAttributes(variables) {
    let updated = false;

    // 确保数据结构存在
    if (!variables.stat_data.属性) return false;

    // 1. 更新生命值上限 = 耐力 * 4
    if (variables.stat_data.属性.耐力 && 
        variables.stat_data.核心状态 && 
        variables.stat_data.核心状态.生命值上限) {

        const endurance = Number(variables.stat_data.属性.耐力.等级[0]) || 0;
        const oldMaxHp = Number(variables.stat_data.核心状态.生命值上限[0]) || 0;
        const newMaxHp = endurance * 4;

        if (oldMaxHp !== newMaxHp) {
            variables.stat_data.核心状态.生命值上限[0] = newMaxHp;

            if (!variables.display_data) {
                variables.display_data = {};
            }
            variables.display_data.生命值上限 = `${oldMaxHp} -> ${newMaxHp} (基于耐力更新)`;
            updated = true;
        }
    }

    // 2. 更新精神值上限 = 意志 * 4
    if (variables.stat_data.属性.意志 && 
        variables.stat_data.核心状态 && 
        variables.stat_data.核心状态.精神值上限) {

        const willpower = Number(variables.stat_data.属性.意志.等级[0]) || 0;
        const oldMaxSp = Number(variables.stat_data.核心状态.精神值上限[0]) || 0;
        const newMaxSp = willpower * 4;

        if (oldMaxSp !== newMaxSp) {
            variables.stat_data.核心状态.精神值上限[0] = newMaxSp;

            if (!variables.display_data) {
                variables.display_data = {};
            }
            variables.display_data.精神值上限 = `${oldMaxSp} -> ${newMaxSp} (基于意志更新)`;
            updated = true;
        }
    }

    // 5. 更新负重上限 = 力量 * 2
    if (variables.stat_data.属性.力量 && 
        variables.stat_data.次生属性 && 
        variables.stat_data.次生属性.负重上限) {

        const strength = Number(variables.stat_data.属性.力量.等级[0]) || 0;
        const oldMaxWeight = Number(variables.stat_data.次生属性.负重上限[0]) || 0;
        const newMaxWeight = strength * 2;

        if (oldMaxWeight !== newMaxWeight) {
            variables.stat_data.次生属性.负重上限[0] = newMaxWeight;

            if (!variables.display_data) {
                variables.display_data = {};
            }
            variables.display_data.负重上限 = `${oldMaxWeight} -> ${newMaxWeight} (基于力量更新)`;
            updated = true;
        }
    }

    // 6. 更新免疫力 = 耐力
    if (variables.stat_data.属性.耐力 && 
        variables.stat_data.次生属性 && 
        variables.stat_data.次生属性.免疫力) {

        const endurance = Number(variables.stat_data.属性.耐力.等级[0]) || 0;
        const oldImmunity = Number(variables.stat_data.次生属性.免疫力[0]) || 0;
        const newImmunity = endurance;

        if (oldImmunity !== newImmunity) {
            variables.stat_data.次生属性.免疫力[0] = newImmunity;

            if (!variables.display_data) {
                variables.display_data = {};
            }
            variables.display_data.免疫力 = `${oldImmunity} -> ${newImmunity} (基于耐力更新)`;
            updated = true;
        }
    }

    return updated;
}

/**
 * Called at the end of a variable update cycle. It finalizes the day count update if necessary.
 *
 * @param {Record<string, any>} variables - The global variables object, which can be modified.
 * @param {boolean} out_is_updated - A flag to be set to true if this function makes any changes.
 * @returns {void}
 */
function variableUpdateEnded(variables, out_is_updated) {
    let isUpdated = out_is_updated || false;

    // 处理天数变更
    if (dayHasPassed) {
        // --- 修正点 2 ---
        // 比较时也使用数组的第一个元素 [0]
        if (variables.stat_data.世界.经过天数[0] === initialDaysPassed) {
            const newDays = initialDaysPassed + 1;

            // --- 修正点 3 ---
            // 更新时，只修改数组的第一个元素 [0]，保留描述信息
            variables.stat_data.世界.经过天数[0] = newDays;

            // 更新 display_data 以提供正确的反馈，例如 "1 -> 2 (天数推进)"
            if (!variables.display_data) {
                variables.display_data = {};
            }
            variables.display_data.经过天数 = `${initialDaysPassed} -> ${newDays} (天数推进)`;

            isUpdated = true;
        }
    }

    // 3. 检查并更新所有属性等级
    attributeList.forEach(attrName => {
        if (updateAttribute(variables, attrName)) {
            isUpdated = true;
        }
    });

    // 4. 检查并更新所有技能等级
    if (updateSkills(variables)) {
        isUpdated = true;
    }

    // 更新所有派生属性
    if (updateDerivedAttributes(variables)) {
        isUpdated = true;
    }

    out_is_updated = isUpdated;
}

