let physio_last_time_str = "";
let physio_saved_states = {};

/**
 * 将数字四舍五入到指定的小数位数。
 * @param {number} num - 需要处理的数字。
 * @param {number} [decimals=12] - 保留的小数位数，默认为12。
 * @returns {number} - 修正精度后的数字。
 */
function roundTo(num, decimals = 12) {
    return parseFloat(num.toFixed(decimals));
}

function parseDateTime(dateTimeStr) {
    return new Date(dateTimeStr);
}

function physiologicalUpdateStarted(variables, out_is_updated) {
    const current_time_str = variables.stat_data.当前时间;
    physio_last_time_str = current_time_str;

    // 保存当前的生理状态值，防止AI修改时被覆盖
    physio_saved_states = {
        碳水: variables.stat_data.生理.碳水,
        脂肪: variables.stat_data.生理.脂肪,
        氮平衡: variables.stat_data.生理.氮平衡,
        蛋白质: variables.stat_data.生理.蛋白质,
        维生素: variables.stat_data.生理.维生素,
        水分: variables.stat_data.生理.水分,
        睡眠: variables.stat_data.精神.睡眠,
        饱腹感: variables.stat_data.次生属性.饱腹感
    };
}

function physiologicalVariableUpdated(_stat_data, path, _oldValue, _newValue) {
    // 如果AI修改了我们要管理的变量，我们需要记录这些变化
    // 但不在这里处理，让AI的修改生效，我们在结束时基于时间差进行自动更新
}

function physiologicalUpdateEnded(variables, out_is_updated) {
    const current_time_str = variables.stat_data.当前时间;
    const current_time = parseDateTime(current_time_str);

    // 计算时间差（分钟）
    if (physio_last_time_str && !isNaN(current_time)) {
        const last_time = parseDateTime(physio_last_time_str);
        const time_diff_ms = current_time - last_time;

        if (time_diff_ms > 0) {
            const minutes_passed = time_diff_ms / (1000 * 60); // 转换为分钟

            // 获取当前值（可能被AI修改过）
            let 碳水 = variables.stat_data.生理.碳水;
            let 脂肪 = variables.stat_data.生理.脂肪;
            let 氮平衡 = variables.stat_data.生理.氮平衡;
            let 蛋白质 = variables.stat_data.生理.蛋白质;
            let 维生素 = variables.stat_data.生理.维生素;
            let 水分 = variables.stat_data.生理.水分;
            let 睡眠 = variables.stat_data.精神.睡眠;
            let 饱腹感 = variables.stat_data.次生属性.饱腹感;

            // 1. 碳水每小时自动-100，最小值0
            碳水 = Math.max(0, 碳水 - (100 * minutes_passed / 60));

            // 2. 当碳水小于100时，每小时-100脂肪，最小值0
            if (碳水 < 100) {
                脂肪 = Math.max(0, 脂肪 - (100 * minutes_passed / 60));
            }

            // 3. 每小时-1氮平衡，范围[-100,100]
            氮平衡 = Math.max(-100, Math.min(100, 氮平衡 - (1 * minutes_passed / 60)));

            // 4. 蛋白质每小时+ 氮平衡的五分之一，无论氮平衡的正负数
            蛋白质 = 蛋白质 + (氮平衡 / 5 * minutes_passed / 60);

            // 5. 维生素每小时-0.5，最低0
            维生素 = Math.max(0, 维生素 - (0.5 * minutes_passed / 60));

            // 6. 水分每小时-1.5，最低0
            水分 = Math.max(0, 水分 - (1.5 * minutes_passed / 60));

            // 7. 睡眠每小时-2，最低0
            睡眠 = Math.max(0, 睡眠 - (2 * minutes_passed / 60));

            // 8. 饱腹感每小时-10，最低0
            饱腹感 = Math.max(0, 饱腹感 - (10 * minutes_passed / 60));

            // 更新变量（使用精度修正）
            variables.stat_data.生理.碳水 = Math.round(碳水); // 碳水必须为整数
            variables.stat_data.生理.脂肪 = Math.round(脂肪); // 脂肪通常也是整数
            variables.stat_data.生理.氮平衡 = Math.round(氮平衡); // 氮平衡通常是整数
            variables.stat_data.生理.蛋白质 = Math.round(蛋白质); // 蛋白质通常是整数
            variables.stat_data.生理.维生素 = Math.round(维生素); // 维生素通常是整数
            variables.stat_data.生理.水分 = Math.round(水分); // 水分通常是整数
            variables.stat_data.精神.睡眠 = Math.round(睡眠); // 睡眠通常是整数
            variables.stat_data.次生属性.饱腹感 = Math.round(饱腹感); // 饱腹感通常是整数

            out_is_updated = true;
        }
    }

