// 新增一个函数来创建和附加状态效果（版本 2：处理 [0] 内的数据）
function createStatusEffects(container, data) {
    // 1. 安全地获取 `当前状态` 数组
    const rawStatusData = data?.["状态"]?.["当前状态"];

    // 2. 检查 `当前状态` 是否为一个非空数组
    if (!rawStatusData || !Array.isArray(rawStatusData) || rawStatusData.length === 0) {
        return; // 如果数据不存在或格式不正确，则直接退出
    }

    // 3. 提取第一个元素，这才是我们真正需要的数据源
    const effectsSource = rawStatusData[0];
    let effectsList = [];

    // 4. 处理数据源，它可能是数组，也可能是字符串
    if (Array.isArray(effectsSource)) {
        // 如果数据源本身就是个数组 (例如: ["寒冷", "疲惫"])，直接使用
        effectsList = effectsSource;
    } else if (typeof effectsSource === 'string' && effectsSource.trim() !== '') {
        // 如果是字符串 (例如: "寒冷,疲惫" 或 "寒冷 疲惫")，则进行分割
        // 这个正则表达式可以同时处理逗号和空格作为分隔符
        effectsList = effectsSource.split(/[,\s]+/).filter(Boolean); // filter(Boolean) 用于移除分割后可能产生的空字符串
    }

    // 5. 如果最终没有可显示的状态，则退出
    if (effectsList.length === 0) {
        return;
    }

    // --- 后续的 DOM 创建逻辑与之前相同 ---

    // 创建主容器
    const $container = $('<div>').addClass('status-effects-container');

    // 创建标题
    const $title = $('<div>').addClass('section__title').text('当前状态');
    $container.append($title);

    // 创建状态列表的容器
    const $list = $('<div>').addClass('status-effects-list');

    // 遍历处理好的状态列表，为每个状态创建一个元素
    effectsList.forEach(effect => {
        if (typeof effect === 'string' && effect.trim() !== '') {
            const $item = $('<span>').addClass('status-effect-item').text(effect);
            $list.append($item);
        }
    });

    // 如果列表不为空，则将整个部分添加到主UI容器中
    if ($list.children().length > 0) {
        $container.append($list);
        container.append($container);
    }
}
