const MAP_STORAGE_KEY = 'survivalGameMapState';

let savedMapState = null;
try {
    const storedData = localStorage.getItem(MAP_STORAGE_KEY);
    if (storedData) {
        savedMapState = JSON.parse(storedData);
    }
} catch (e) {
    console.error("Error loading map state from localStorage:", e);
    savedMapState = null;
}


class CustomMap {
    constructor(containerElement) {
        this.markers = [];
        this.links = [];
        this.scale = 1;
        this.translateX = 0;
        this.translateY = 0;
        this.isDragging = false;
        this.dragStarted = false;
        this.isPinching = false;
        this.initialPinchDistance = 0;
        this.lastX = 0;
        this.lastY = 0;
        this.clickStartTime = 0;
        this.clickStartX = 0;
        this.clickStartY = 0;
        this.activeMarker = null;
        this.markerIdCounter = 0;
        this.linkingFrom = null;

        this.containerElement = containerElement;
        this.initElements();
        this.initEventListeners();

        if (!savedMapState) {
            this.translateX = this.mapContainer.clientWidth / 2;
            this.translateY = this.mapContainer.clientHeight / 2;
        }
        this.updateTransform();
    }

    initElements() {
        this.mapContainer = this.containerElement.querySelector('.map-container');
        this.mapCanvas = this.containerElement.querySelector('.map-canvas');
        this.markerColorPicker = this.containerElement.querySelector('.color-picker');
        this.clearAllBtn = this.containerElement.querySelector('#clearAll');
        this.clearLinksBtn = this.containerElement.querySelector('#clearLinks');
        this.zoomInBtn = this.containerElement.querySelector('#zoomIn');
        this.zoomOutBtn = this.containerElement.querySelector('#zoomOut');

        const svgNS = "http://www.w3.org/2000/svg";
        this.svg = document.createElementNS(svgNS, 'svg');
        this.svg.classList.add('lines-svg');
        this.mapCanvas.appendChild(this.svg);
    }

    getEventCoords(e) {
        if (e.touches && e.touches.length > 0) {
            return { x: e.touches[0].clientX, y: e.touches[0].clientY };
        }
        return { x: e.clientX, y: e.clientY };
    }

    initEventListeners() {
        if (this.clearAllBtn) this.clearAllBtn.addEventListener('click', () => this.clearAllData());
        if (this.clearLinksBtn) this.clearLinksBtn.addEventListener('click', () => this.clearAllLinks());

        this.mapContainer.addEventListener('mousedown', (e) => this.handleDragStart(e));
        this.mapContainer.addEventListener('mousemove', (e) => this.handleDragMove(e));
        this.mapContainer.addEventListener('mouseup', (e) => this.handleDragEnd(e));
        this.mapContainer.addEventListener('mouseleave', () => this.endDrag());

        this.mapContainer.addEventListener('touchstart', (e) => this.handleDragStart(e), { passive: false });
        this.mapContainer.addEventListener('touchmove', (e) => this.handleDragMove(e), { passive: false });
        this.mapContainer.addEventListener('touchend', (e) => this.handleDragEnd(e));
        this.mapContainer.addEventListener('touchcancel', () => this.endDrag());

        this.mapContainer.addEventListener('wheel', (e) => this.handleWheel(e));

        if (this.zoomInBtn) this.zoomInBtn.addEventListener('click', (e) => this.zoom(1.2, e));
        if (this.zoomOutBtn) this.zoomOutBtn.addEventListener('click', (e) => this.zoom(0.8, e));

        this.mapContainer.addEventListener('contextmenu', (e) => {
            e.preventDefault();
            if (this.linkingFrom) this.cancelLinking();
        });

        document.addEventListener('click', (e) => {
            if (this.activeMarker && !e.target.closest('.marker')) {
                this.closeActiveMarker();
            }
        });
    }

    handleDragStart(e) {
        if (this.linkingFrom) return;
        e.preventDefault();
        if (e.target.closest('.marker')) return;

        if (e.touches && e.touches.length === 2) {
            this.isPinching = true;
            this.initialPinchDistance = this.getPinchDistance(e);
            return;
        }

        const coords = this.getEventCoords(e);
        this.clickStartTime = Date.now();
        this.clickStartX = coords.x;
        this.clickStartY = coords.y;
        this.lastX = coords.x;
        this.lastY = coords.y;
        this.dragStarted = false;
        this.isDragging = true;
        this.mapContainer.classList.add('dragging');
    }

    handleDragMove(e) {
        if (this.linkingFrom) return;
        e.preventDefault();

        if (this.isPinching && e.touches && e.touches.length === 2) {
            const newDist = this.getPinchDistance(e);
            const scaleFactor = newDist / this.initialPinchDistance;
            this.zoom(scaleFactor, e);
            this.initialPinchDistance = newDist;
            return;
        }

        if (this.isDragging) {
            const coords = this.getEventCoords(e);
            const deltaX = coords.x - this.lastX;
            const deltaY = coords.y - this.lastY;

            if (!this.dragStarted && (Math.abs(deltaX) > 3 || Math.abs(deltaY) > 3)) {
                this.dragStarted = true;
            }

            this.translateX += deltaX;
            this.translateY += deltaY;
            this.updateTransform();

            this.lastX = coords.x;
            this.lastY = coords.y;
        }
    }

    handleDragEnd(e) {
        const wasPinching = this.isPinching;
        this.endDrag();

        if (wasPinching || this.linkingFrom) return;
        if (e.target.closest('.marker')) return;

        const coords = this.getEventCoords(e.changedTouches ? e.changedTouches[0] : e);
        const clickDuration = Date.now() - this.clickStartTime;
        const clickDistance = Math.hypot(coords.x - this.clickStartX, coords.y - this.clickStartY);

        if (clickDuration < 300 && clickDistance < 10 && !this.dragStarted) {
            const rect = this.mapContainer.getBoundingClientRect();
            const x = (coords.x - rect.left - this.translateX) / this.scale;
            const y = (coords.y - rect.top - this.translateY) / this.scale;
            this.addMarker(x, y);
        }
    }

    endDrag() {
        this.isDragging = false;
        this.isPinching = false;
        this.dragStarted = false;
        this.mapContainer.classList.remove('dragging');
    }

    addMarker(x, y) {
        this.closeActiveMarker();
        const markerId = `marker-${this.markerIdCounter++}`;
        const markerColor = this.markerColorPicker ? this.markerColorPicker.value : '#4dabf7';

        const markerEl = document.createElement('div');
        markerEl.className = 'marker empty';
        markerEl.id = markerId;
        markerEl.style.borderColor = markerColor;
        markerEl.style.color = markerColor;
        markerEl.style.left = `${x}px`;
        markerEl.style.top = `${y}px`;
        markerEl.style.transform = `translate(-50%, -50%)`;

        this.mapCanvas.appendChild(markerEl);

        const markerData = { id: markerId, element: markerEl, x, y, color: markerColor, text: '' };
        this.markers.push(markerData);

        this.bindMarkerEvents(markerEl, markerData);
        setTimeout(() => this.editMarker(markerData), 100);
    }

    addMarkerFromData(data) {
        const markerEl = document.createElement('div');
        markerEl.className = 'marker';
        markerEl.id = data.id;
        markerEl.style.borderColor = data.color;
        markerEl.style.color = data.color;
        markerEl.style.left = `${data.x}px`;
        markerEl.style.top = `${data.y}px`;
        markerEl.style.transform = `translate(-50%, -50%)`;

        if (data.text.trim()) {
            markerEl.innerText = data.text;
        } else {
            markerEl.classList.add('empty');
        }

        this.mapCanvas.appendChild(markerEl);
        const markerData = { ...data, element: markerEl };
        this.markers.push(markerData);
        this.bindMarkerEvents(markerEl, markerData);
    }


    bindMarkerEvents(markerEl, markerData) {
        markerEl.addEventListener('click', (e) => {
            e.stopPropagation();
            if (this.linkingFrom) {
                if (this.linkingFrom !== markerData.id) {
                    this.createLink(this.linkingFrom, markerData.id);
                }
                this.cancelLinking();
                return;
            }

            if (!markerEl.classList.contains('editing')) {
              this.editMarker(markerData);
            }
        });
    }

    editMarker(markerData) {
        const markerEl = markerData.element;
        if (this.activeMarker && this.activeMarker !== markerEl) {
            this.closeActiveMarker();
        }
        markerEl.classList.add('editing');
        markerEl.classList.remove('empty');
        this.activeMarker = markerEl;

        const currentHoverTransform = markerEl.style.transform;
        markerEl.style.transform = 'translate(-50%, -50%)';

        const input = document.createElement('input');
        input.type = 'text';
        input.className = 'marker-input';
        input.value = markerData.text;
        input.placeholder = '输入文本...';

        const controls = document.createElement('div');
        controls.className = 'marker-controls';
        controls.innerHTML = `<button class="save-btn">保存</button><button class="link-btn">连线</button><button class="delete-btn">删除</button>`;

        markerEl.innerHTML = '';
        markerEl.appendChild(input);
        markerEl.appendChild(controls);

        const saveAction = () => {
            markerEl.style.transform = currentHoverTransform;
            this.saveMarker(markerData, input.value);
        }

        controls.querySelector('.save-btn').addEventListener('click', (e) => { e.stopPropagation(); saveAction(); });
        controls.querySelector('.delete-btn').addEventListener('click', (e) => { e.stopPropagation(); this.deleteMarker(markerData); });
        controls.querySelector('.link-btn').addEventListener('click', (e) => { e.stopPropagation(); this.startLinking(markerData.id); });

        input.addEventListener('keypress', (e) => { if (e.key === 'Enter') saveAction(); });
        input.addEventListener('blur', () => saveAction());

        setTimeout(() => input.focus(), 50);
    }

    saveMarker(markerData, text) {
        markerData.text = text;
        const markerEl = markerData.element;
        markerEl.classList.remove('editing');
        if (text.trim()) {
            markerEl.innerHTML = text;
            markerEl.classList.remove('empty');
        } else {
            markerEl.innerHTML = '';
            markerEl.classList.add('empty');
        }
        if (this.activeMarker === markerEl) {
            this.activeMarker = null;
        }
    }

    closeActiveMarker() {
        if (this.activeMarker) {
            const markerData = this.markers.find(m => m.element === this.activeMarker);
            if (markerData) {
                 const input = this.activeMarker.querySelector('.marker-input');
                 if (input) {
                    this.saveMarker(markerData, input.value);
                 }
            }
        }
    }

    deleteMarker(markerData) {
        this.closeActiveMarker();
        markerData.element.remove();
        this.markers = this.markers.filter(m => m.id !== markerData.id);

        const linksToRemove = this.links.filter(link => link.from === markerData.id || link.to === markerData.id);
        linksToRemove.forEach(link => this.removeLink(link));
        this.drawLinks();

        if (this.activeMarker === markerData.element) this.activeMarker = null;
    }

    clearAllData() {
        this.closeActiveMarker();
        this.markers.forEach(md => md.element.remove());
        this.markers = [];
        this.activeMarker = null;
        this.links = [];
        this.drawLinks();
        try {
            localStorage.removeItem(MAP_STORAGE_KEY);
            savedMapState = null;
        } catch (e) {
            console.error("Error clearing map state from localStorage:", e);
        }
    }

    handleWheel(e) {
        e.preventDefault();
        const delta = e.deltaY > 0 ? 0.9 : 1.1;
        this.zoom(delta, e);
    }

    getPinchDistance(e) {
        const t1 = e.touches[0];
        const t2 = e.touches[1];
        return Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
    }

    zoom(factor, event) {
        const newScale = this.scale * factor;
        if (newScale < 0.2 || newScale > 5) return;

        const rect = this.mapContainer.getBoundingClientRect();
        let mouseX, mouseY;

        if (event) {
            const coords = this.getEventCoords(event);
            mouseX = coords.x - rect.left;
            mouseY = coords.y - rect.top;
        } else {
            mouseX = rect.width / 2;
            mouseY = rect.height / 2;
        }

        this.translateX = mouseX - (mouseX - this.translateX) * factor;
        this.translateY = mouseY - (mouseY - this.translateY) * factor;
        this.scale = newScale;

        this.updateTransform();
    }

    updateTransform() {
        this.mapCanvas.style.transform = `translate(${this.translateX}px, ${this.translateY}px) scale(${this.scale})`;
        this.mapCanvas.style.setProperty('--bg-pos-x', `${this.translateX}px`);
        this.mapCanvas.style.setProperty('--bg-pos-y', `${this.translateY}px`);
    }

    // --- LINKING METHODS ---

    startLinking(markerId) {
        this.closeActiveMarker();
        this.linkingFrom = markerId;
        const markerData = this.markers.find(m => m.id === markerId);
        if (markerData) {
            markerData.element.classList.add('linking-source');
        }
        this.mapContainer.classList.add('linking');
    }

    cancelLinking() {
        if (!this.linkingFrom) return;
        const markerData = this.markers.find(m => m.id === this.linkingFrom);
        if (markerData) {
            markerData.element.classList.remove('linking-source');
        }
        this.linkingFrom = null;
        this.mapContainer.classList.remove('linking');
    }

    createLink(fromId, toId) {
        const exists = this.links.some(link => 
            (link.from === fromId && link.to === toId) || 
            (link.from === toId && link.to === fromId)
        );
        if (exists) return;

        const link = { from: fromId, to: toId };
        this.links.push(link);
        this.drawLinks();
    }

    removeLink(linkToRemove) {
        this.links = this.links.filter(link => link !== linkToRemove);
    }

    clearAllLinks() {
        if (this.links.length === 0) return;
        this.links = [];
        this.drawLinks();
    }

    drawLinks() {
        this.svg.innerHTML = '';
        const svgNS = "http://www.w3.org/2000/svg";

        this.links.forEach(link => {
            const fromMarker = this.markers.find(m => m.id === link.from);
            const toMarker = this.markers.find(m => m.id === link.to);

            if (fromMarker && toMarker) {
                const line = document.createElementNS(svgNS, 'line');
                line.setAttribute('x1', fromMarker.x);
                line.setAttribute('y1', fromMarker.y);
                line.setAttribute('x2', toMarker.x);
                line.setAttribute('y2', toMarker.y);
                line.setAttribute('stroke', 'rgba(255, 255, 255, 0.5)');
                line.setAttribute('stroke-width', '2');
                line.setAttribute('stroke-dasharray', '5, 5');
                this.svg.appendChild(line);
            }
        });
    }


    // --- STATE MANAGEMENT ---

    loadState(state) {
        this.scale = state.scale || 1;
        this.translateX = state.translateX || 0;
        this.translateY = state.translateY || 0;
        this.links = state.links || [];

        this.markers.forEach(md => md.element.remove());
        this.markers = [];
        this.activeMarker = null;

        if (state.markers) {
            state.markers.forEach(markerData => {
                this.addMarkerFromData(markerData);
            });
        }

        if (state.markers && state.markers.length > 0) {
            const maxId = Math.max(...state.markers.map(m => parseInt(m.id.split('-')[1] || 0, 10)));
            this.markerIdCounter = isFinite(maxId) ? maxId + 1 : 0;
        } else {
            this.markerIdCounter = 0;
        }

        // FIX: The drawLinks() call must be AFTER markers are loaded.
        this.drawLinks();
        this.updateTransform();
    }
}

function m() {
    const modal = $('<div>').addClass('map-modal');
    const content = $('<div>').addClass('map-modal__content');

    const mapHtml = `
        <div class="container">
            <div class="toolbar">
                <label>标记颜色：<input type="color" class="color-picker" value="#4dabf7" title="标记颜色"></label>
                <button id="clearLinks">清除连线</button>
                <button id="clearAll" class="clear-btn">清除所有</button>
            </div>
            <div class="map-container">
                <div class="map-canvas"></div>
            </div>
            <div class="info-panel">
                <strong>操作说明：</strong><br>
                • 右键或再次点击连线按钮取消连线<br>
                • 拖拽/单指滑动移动地图<br>
                • 滚轮/双指捏合缩放
            </div>
            <div class="zoom-controls">
                <button class="zoom-btn" id="zoomIn">+</button>
                <button class="zoom-btn" id="zoomOut">−</button>
            </div>
        </div>`;

    content.append(mapHtml);

    let mapInstance;
    const closeBtn = $('<span>').addClass('map-modal__close').html('×').on('click', () => {
        if (mapInstance) {
            mapInstance.closeActiveMarker();
            const stateToSave = {
                markers: mapInstance.markers.map(m => ({
                    id: m.id,
                    x: m.x,
                    y: m.y,
                    color: m.color,
                    text: m.text
                })),
                links: mapInstance.links,
                scale: mapInstance.scale,
                translateX: mapInstance.translateX,
                translateY: mapInstance.translateY
            };

            try {
                localStorage.setItem(MAP_STORAGE_KEY, JSON.stringify(stateToSave));
                savedMapState = stateToSave;
            } catch (e) {
                console.error("Error saving map state to localStorage:", e);
            }
        }
        modal.remove();
    });

    modal.append(content, closeBtn);
    $('body').append(modal);

    const mapContainerElement = modal.find('.container')[0];
    mapInstance = new CustomMap(mapContainerElement);

    if (savedMapState) {
        mapInstance.loadState(savedMapState);
    }
}

